-- Issue #6735. Synthetic fixture; table, privilege and membership change
-- rolled back. Execute exact migration, never a copied grant.
BEGIN;
ALTER TABLE dflow_prod."Roles" RENAME TO role_create_6735_saved;
CREATE TABLE dflow_prod."Roles" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT role_create_6735_fixture_pk PRIMARY KEY,
  "Name" varchar(255) NOT NULL,
  kind text NOT NULL DEFAULT 'leaf',
  parent_id integer,
  is_active boolean NOT NULL DEFAULT true,
  app_role_id uuid
);
INSERT INTO dflow_prod."Roles" ("Name",kind,parent_id,is_active)
VALUES ('ZZ Fixture category','category',NULL,true);
GRANT SELECT ON dflow_prod."Roles" TO designflow_prod_backend_grants;
DO $before$
BEGIN
  IF has_table_privilege('designflow_prod_backend_runtime','dflow_prod."Roles"','INSERT')
     OR has_column_privilege('designflow_prod_backend_runtime','dflow_prod."Roles"','Name','INSERT') THEN
    RAISE EXCEPTION 'Fixture must reproduce missing create privilege';
  END IF;
  IF NOT pg_has_role(current_user, 'designflow_prod_backend_runtime', 'SET') THEN
    EXECUTE format('GRANT designflow_prod_backend_runtime TO %I WITH SET TRUE', current_user);
  END IF;
END
$before$;
\ir ../migrations/20261219003000_dflow_prod_role_create_insert_grant.sql
DO $contract$
DECLARE c text;
BEGIN
  FOREACH c IN ARRAY ARRAY['Name','kind','parent_id','is_active'] LOOP
    IF NOT has_column_privilege('designflow_prod_backend_runtime','dflow_prod."Roles"',c,'INSERT') THEN
      RAISE EXCEPTION 'Runtime cannot insert %', c;
    END IF;
  END LOOP;
  FOREACH c IN ARRAY ARRAY['Id','app_role_id'] LOOP
    IF has_column_privilege('designflow_prod_backend_runtime','dflow_prod."Roles"',c,'INSERT') THEN
      RAISE EXCEPTION 'Runtime must not insert %', c;
    END IF;
  END LOOP;
  IF has_table_privilege('designflow_prod_backend_runtime','dflow_prod."Roles"','DELETE') THEN
    RAISE EXCEPTION 'Runtime acquired DELETE';
  END IF;
END
$contract$;
DO $behavior$
DECLARE parent integer; new_id integer;
BEGIN
  SELECT "Id" INTO STRICT parent FROM dflow_prod."Roles" WHERE kind='category' LIMIT 1;
  SET LOCAL ROLE designflow_prod_backend_runtime;
  INSERT INTO dflow_prod."Roles" ("Name",kind,parent_id,is_active)
  VALUES ('contract-6735-leaf','leaf',parent,true) RETURNING "Id" INTO new_id;
  IF new_id IS NULL THEN RAISE EXCEPTION 'Runtime create returned no id'; END IF;
  BEGIN
    DELETE FROM dflow_prod."Roles" WHERE "Id"=new_id;
    RAISE EXCEPTION 'Runtime acquired DELETE';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  RESET ROLE;
END
$behavior$;
ROLLBACK;
